  it('adds only the single highest helpful and hindering Status', () => {
    const sheet = makeSheet({
      Statuses: [
        makeStatus({ Id: 'st-a', Name: 'Prepared', Rank: 2, Polarity: 'Positive' }),
        makeStatus({ Id: 'st-b', Name: 'Sharp', Rank: 1, Polarity: 'Positive' }),
        makeStatus({ Id: 'st-c', Name: 'Rattled', Rank: 3, Polarity: 'Negative' }),
        makeStatus({ Id: 'st-d', Name: 'Exposed', Rank: 1, Polarity: 'Negative' }),
      ],
    });
    const b = computeRollBreakdown(sheet, 'v-might', library);
    // base 1 + helpful 2 (Prepared) - hindering 3 (Rattled) = 0
    expect(b.Total).toBe(0);
    expect(b.Sources.filter((s) => s.Kind === 'Status')).toHaveLength(2);
  });

  it('ignores Neutral Statuses in roll breakdown - they do not count as helpful or hindering', () => {
    const sheet = makeSheet({
      Statuses: [
        makeStatus({ Id: 'st-a', Name: 'Prepared', Rank: 1, Polarity: 'Positive' }),
        makeStatus({ Id: 'st-b', Name: 'Watched', Rank: 5, Polarity: 'Neutral' }),
      ],
    });
    const b = computeRollBreakdown(sheet, 'v-might', library);
    // base 1 + helpful 1 (Prepared) + no hindering (Watched is Neutral) = 2
    expect(b.Total).toBe(2);
    const statusSources = b.Sources.filter((s) => s.Kind === 'Status');
    expect(statusSources).toHaveLength(1);
    expect(statusSources[0]).toMatchObject({ Label: 'Prepared (highest helpful Status)', Value: 1 });
  });

  it('reports the highest Negative Status as hindering even when a Neutral Status has higher Rank', () => {
    const sheet = makeSheet({
      Statuses: [
        makeStatus({ Id: 'st-a', Name: 'Rattled', Rank: 2, Polarity: 'Negative' }),
        makeStatus({ Id: 'st-b', Name: 'Watched', Rank: 5, Polarity: 'Neutral' }),
      ],
    });
    const b = computeRollBreakdown(sheet, 'v-might', library);
    // base 1 + no helpful + hindered -2 (Rattled is highest Negative, not Watched which is Neutral) = -1
    expect(b.Total).toBe(-1);
    const statusSources = b.Sources.filter((s) => s.Kind === 'Status');
    expect(statusSources).toHaveLength(1);
    expect(statusSources[0]).toMatchObject({ Label: 'Rattled (highest hindering Status)', Value: -2 });
  });
});

