    expect(statusSources).toHaveLength(1);
    expect(statusSources[0]).toMatchObject({ Label: 'Prepared (highest helpful Status)', Value: 1 });
  });

  it('reports the highest Negative Status as hindering even when a Neutral Status has higher Rank', () => {
