        { Id: 'ab-test', Name: 'Test', RulesText: '', Acquisition: 'Starting', Tags: [], Effects: [{ Kind: 'RollBonus', Value: 2, Duration: 'Permanent', AppliesToVirtueId: 'v-might' }] },
